    let metrics = field_chrome_metrics(Some(crate::wgpu::text::line_height(FIELD_DETAIL_FONT_SIZE)), 0.0, Some(crate::wgpu::text::line_height(FIELD_DETAIL_FONT_SIZE)), theme.gap_standard);
    let mut fixture = Fixture::new();
